REVOKE ALL ON FUNCTION public.hiring7_copy_milestones(),public.hiring7_stage_delete_guard(),public.hiring7_stage_guard() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.hiring7_stage_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.stage_key IS DISTINCT FROM OLD.stage_key AND NEW.stage_key IN ('paused','ended') THEN IF coalesce(btrim(NEW.end_reason),'')='' THEN NEW.end_reason:=nullif(current_setting('hiring7.reason',true),''); END IF; IF coalesce(btrim(NEW.end_reason),'')='' THEN RAISE EXCEPTION 'A reason is required for Paused or Ended'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.hiring7_move_journey(_id uuid,_stage text,_note text,_visible boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Hiring admin required' USING ERRCODE='42501'; END IF; IF _stage IN ('paused','ended') AND coalesce(btrim(_note),'')='' THEN RAISE EXCEPTION 'A reason is required for Paused or Ended'; END IF; PERFORM set_config('hiring7.reason',_note,true); RETURN public.change_journey_stage(_id,_stage,_note,_visible); END $$;
ALTER FUNCTION public.hiring7_copy_milestones() SET SCHEMA hiring_private;
ALTER FUNCTION public.hiring7_stage_delete_guard() SET SCHEMA hiring_private;
ALTER FUNCTION public.start_journey(uuid,uuid,date) SET SCHEMA hiring_private;
ALTER FUNCTION public.hiring7_move_journey(uuid,text,text,boolean) SET SCHEMA hiring_private;
ALTER FUNCTION public.hiring7_set_mentor(uuid,uuid) SET SCHEMA hiring_private;
ALTER FUNCTION public.grant_hiring_role(text,public.app_role) SET SCHEMA hiring_private;
ALTER FUNCTION public.revoke_hiring_role(uuid,public.app_role) SET SCHEMA hiring_private;
ALTER FUNCTION public.hiring7_staff_roles() SET SCHEMA hiring_private;
ALTER FUNCTION public.hiring7_save_letter(text,text,text,boolean) SET SCHEMA hiring_private;
CREATE FUNCTION public.start_journey(_application_id uuid,_mentor_id uuid,_start_date date) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT hiring_private.start_journey(_application_id,_mentor_id,_start_date) $$;
CREATE FUNCTION public.hiring7_move_journey(_id uuid,_stage text,_note text,_visible boolean) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT hiring_private.hiring7_move_journey(_id,_stage,_note,_visible) $$;
CREATE FUNCTION public.hiring7_set_mentor(_id uuid,_mentor uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT hiring_private.hiring7_set_mentor(_id,_mentor) $$;
CREATE FUNCTION public.grant_hiring_role(_email text,_role public.app_role) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT hiring_private.grant_hiring_role(_email,_role) $$;
CREATE FUNCTION public.revoke_hiring_role(_user_id uuid,_role public.app_role) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT hiring_private.revoke_hiring_role(_user_id,_role) $$;
CREATE FUNCTION public.hiring7_staff_roles() RETURNS TABLE(user_id uuid,email text,full_name text,roles text[],is_owner boolean) LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT * FROM hiring_private.hiring7_staff_roles() $$;
CREATE FUNCTION public.hiring7_save_letter(_kind text,_name text,_body text,_pending boolean) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT hiring_private.hiring7_save_letter(_kind,_name,_body,_pending) $$;
DO $$ DECLARE name text; BEGIN FOREACH name IN ARRAY ARRAY['start_journey(uuid,uuid,date)','hiring7_move_journey(uuid,text,text,boolean)','hiring7_set_mentor(uuid,uuid)','grant_hiring_role(text,public.app_role)','revoke_hiring_role(uuid,public.app_role)','hiring7_staff_roles()','hiring7_save_letter(text,text,text,boolean)'] LOOP EXECUTE 'REVOKE ALL ON FUNCTION public.'||name||' FROM PUBLIC,anon'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.'||name||' TO authenticated,service_role'; END LOOP; END $$;